INSERT INTO public.ta_lessons(course_slug,lesson_no,title_pl,material) VALUES
('rymarz',0,'1. Rymarstwo a kaletnictwo: wyroby i siły','{"curriculum_revision":11,"editorial_status":"review_needed","lesson_kind":"technical_curriculum","module":1,"illustration":"craft-rymarz","sections":[{"heading":"Co musisz zrozumieć","text":"Rymarz wykonuje i naprawia skórzane pasy, uprzęże i elementy wyposażenia jeździeckiego. Kaletnik skupia się na torbach i drobnych wyrobach. Element przenoszący obciążenie wymaga szczególnej kontroli, nie wystarczy ładny szew."},{"heading":"Materiały i narzędzia w praktyce","text":"Zanim rozpoczniesz etap „Rymarstwo a kaletnictwo: wyroby i siły”, zapisz parametry próbki, warunki użytkowania, narzędzia i ograniczenia. Rymarz wykonuje i naprawia skórzane pasy, uprzęże i elementy wyposażenia jeździeckiego. Kaletnik skupia się na torbach i drobnych wyrobach. Element przenoszący obciążenie wymaga szczególnej kontroli, nie wystarczy ładny szew."},{"heading":"Przykład i obliczenia","text":"Rozrysuj drogę siły od sprzączki przez pas do mocowania. Zaznacz dziurki, szew i miejsca zgięcia."},{"heading":"Błąd, który trzeba rozpoznać","text":"Pytanie kontrolne: Pas pęka przy dziurce, choć skóra poza nią wygląda dobrze. Dlaczego? Otwory i krawędzie koncentracją naprężeń osłabiają przekrój."},{"heading":"Ćwiczenie i weryfikacja","text":"Rozrysuj drogę siły od sprzączki przez pas do mocowania. Zaznacz dziurki, szew i miejsca zgięcia. Uzasadnij dobór i sprawdź wynik z prowadzącym; elementu demonstracyjnego nie używaj do pracy z żywym zwierzęciem ani pod obciążeniem."}],"references":[{"label":"Leather Working Group — leather manufacturing and responsible sourcing","url":"https://www.leatherworkinggroup.com/"},{"label":"The Leather Conservation Centre — care and conservation","url":"https://www.leatherconservation.org/"},{"label":"British Horse Society — horse welfare and tack","url":"https://www.bhs.org.uk/"}],"learning":{"intro":"Rymarz wykonuje i naprawia skórzane pasy, uprzęże i elementy wyposażenia jeździeckiego. Kaletnik skupia się na torbach i drobnych wyrobach. Element przenoszący obciążenie wymaga szczególnej kontroli, nie wystarczy ładny szew.","situation":"Pas pęka przy dziurce, choć skóra poza nią wygląda dobrze. Dlaczego?","task":"Rozrysuj drogę siły od sprzączki przez pas do mocowania. Zaznacz dziurki, szew i miejsca zgięcia.","question":"Pas pęka przy dziurce, choć skóra poza nią wygląda dobrze. Dlaczego?","options":["Skóra ma jednolitą wytrzymałość niezależnie od otworów.","Otwory i krawędzie tworzą koncentrację naprężeń.","Kolor sprzączki decyduje o sile zrywającej.","Tylko długość pasa ma znaczenie."],"correct":1,"explanation":"Otwory i krawędzie koncentracją naprężeń osłabiają przekrój.","feedback":["Nie. Otwory i krawędzie koncentracją naprężeń osłabiają przekrój.","Poprawnie. Otwory i krawędzie koncentracją naprężeń osłabiają przekrój.","Nie. Otwory i krawędzie koncentracją naprężeń osłabiają przekrój.","Nie. Otwory i krawędzie koncentracją naprężeń osłabiają przekrój."]}}'::jsonb),
('rymarz',1,'2. Anatomia skóry i kierunek rozkroju','{"curriculum_revision":11,"editorial_status":"review_needed","lesson_kind":"technical_curriculum","module":1,"illustration":"craft-rymarz","sections":[{"heading":"Co musisz zrozumieć","text":"Skóra nie jest materiałem jednorodnym. Grzbiet i krupon zwykle mają inną strukturę włókien niż partie brzucha; ważne są blizny, rozciągliwość i kierunek pracy paska."},{"heading":"Materiały i narzędzia w praktyce","text":"Zanim rozpoczniesz etap „Anatomia skóry i kierunek rozkroju”, zapisz parametry próbki, warunki użytkowania, narzędzia i ograniczenia. Skóra nie jest materiałem jednorodnym. Grzbiet i krupon zwykle mają inną strukturę włókien niż partie brzucha; ważne są blizny, rozciągliwość i kierunek pracy paska."},{"heading":"Przykład i obliczenia","text":"Na papierowym szablonie zaznacz miejsca wymagające stabilności wymiarowej, unikaj wad i rozciągliwych stref."},{"heading":"Błąd, który trzeba rozpoznać","text":"Pytanie kontrolne: Dlaczego pas z miękkiej rozciągliwej części brzucha może wydłużać się nierówno? Ułożenie i gęstość włókien zależą od partii skóry."},{"heading":"Ćwiczenie i weryfikacja","text":"Na papierowym szablonie zaznacz miejsca wymagające stabilności wymiarowej, unikaj wad i rozciągliwych stref. Uzasadnij dobór i sprawdź wynik z prowadzącym; elementu demonstracyjnego nie używaj do pracy z żywym zwierzęciem ani pod obciążeniem."}],"references":[{"label":"Leather Working Group — leather manufacturing and responsible sourcing","url":"https://www.leatherworkinggroup.com/"},{"label":"The Leather Conservation Centre — care and conservation","url":"https://www.leatherconservation.org/"},{"label":"British Horse Society — horse welfare and tack","url":"https://www.bhs.org.uk/"}],"learning":{"intro":"Skóra nie jest materiałem jednorodnym. Grzbiet i krupon zwykle mają inną strukturę włókien niż partie brzucha; ważne są blizny, rozciągliwość i kierunek pracy paska.","situation":"Dlaczego pas z miękkiej rozciągliwej części brzucha może wydłużać się nierówno?","task":"Na papierowym szablonie zaznacz miejsca wymagające stabilności wymiarowej, unikaj wad i rozciągliwych stref.","question":"Dlaczego pas z miękkiej rozciągliwej części brzucha może wydłużać się nierówno?","options":["Każda część skóry ma te same włókna.","Wydłużenie zależy wyłącznie od farby.","Różna gęstość i orientacja włókien zmieniają rozciąganie.","Wyłącznie długość nici decyduje o odkształceniu."],"correct":2,"explanation":"Ułożenie i gęstość włókien zależą od partii skóry.","feedback":["Nie. Ułożenie i gęstość włókien zależą od partii skóry.","Nie. Ułożenie i gęstość włókien zależą od partii skóry.","Poprawnie. Ułożenie i gęstość włókien zależą od partii skóry.","Nie. Ułożenie i gęstość włókien zależą od partii skóry."]}}'::jsonb),
('rymarz',2,'3. Garbowanie roślinne i chromowe','{"curriculum_revision":11,"editorial_status":"review_needed","lesson_kind":"technical_curriculum","module":1,"illustration":"craft-rymarz","sections":[{"heading":"Co musisz zrozumieć","text":"Garbowanie stabilizuje kolagen. Skóry garbowane roślinnie często nadają się do formowania i tłoczenia, a chromowo garbowane bywają bardziej miękkie. Wybór zależy od zastosowania, grubości i specyfikacji, nie od hasła marketingowego."},{"heading":"Materiały i narzędzia w praktyce","text":"Zanim rozpoczniesz etap „Garbowanie roślinne i chromowe”, zapisz parametry próbki, warunki użytkowania, narzędzia i ograniczenia. Garbowanie stabilizuje kolagen. Skóry garbowane roślinnie często nadają się do formowania i tłoczenia, a chromowo garbowane bywają bardziej miękkie. Wybór zależy od zastosowania, grubości i specyfikacji, nie od hasła marketingowego."},{"heading":"Przykład i obliczenia","text":"Porównaj próbki na zgięcie, sprężystość i podatność na odkształcenie bez uszkadzania wyrobu."},{"heading":"Błąd, który trzeba rozpoznać","text":"Pytanie kontrolne: Czy garbowanie roślinne automatycznie gwarantuje bezpieczny pas do uprzęży? Nie: potrzebne są dane o skórze, konstrukcji, wykonaniu i wymaganym obciążeniu."},{"heading":"Ćwiczenie i weryfikacja","text":"Porównaj próbki na zgięcie, sprężystość i podatność na odkształcenie bez uszkadzania wyrobu. Uzasadnij dobór i sprawdź wynik z prowadzącym; elementu demonstracyjnego nie używaj do pracy z żywym zwierzęciem ani pod obciążeniem."}],"references":[{"label":"Leather Working Group — leather manufacturing and responsible sourcing","url":"https://www.leatherworkinggroup.com/"},{"label":"The Leather Conservation Centre — care and conservation","url":"https://www.leatherconservation.org/"},{"label":"British Horse Society — horse welfare and tack","url":"https://www.bhs.org.uk/"}],"learning":{"intro":"Garbowanie stabilizuje kolagen. Skóry garbowane roślinnie często nadają się do formowania i tłoczenia, a chromowo garbowane bywają bardziej miękkie. Wybór zależy od zastosowania, grubości i specyfikacji, nie od hasła marketingowego.","situation":"Czy garbowanie roślinne automatycznie gwarantuje bezpieczny pas do uprzęży?","task":"Porównaj próbki na zgięcie, sprężystość i podatność na odkształcenie bez uszkadzania wyrobu.","question":"Czy garbowanie roślinne automatycznie gwarantuje bezpieczny pas do uprzęży?","options":["Tak, bez względu na grubość.","Tak, jeśli skóra jest brązowa.","Tak, jeśli sprzączka jest stalowa.","Nie, o bezpieczeństwie decyduje cały układ i jego ocena."],"correct":3,"explanation":"Nie: potrzebne są dane o skórze, konstrukcji, wykonaniu i wymaganym obciążeniu.","feedback":["Nie. Nie: potrzebne są dane o skórze, konstrukcji, wykonaniu i wymaganym obciążeniu.","Nie. Nie: potrzebne są dane o skórze, konstrukcji, wykonaniu i wymaganym obciążeniu.","Nie. Nie: potrzebne są dane o skórze, konstrukcji, wykonaniu i wymaganym obciążeniu.","Poprawnie. Nie: potrzebne są dane o skórze, konstrukcji, wykonaniu i wymaganym obciążeniu."]}}'::jsonb),
('rymarz',3,'4. Pomiar grubości, szerokości i tolerancji','{"curriculum_revision":11,"editorial_status":"review_needed","lesson_kind":"technical_curriculum","module":2,"illustration":"craft-rymarz","sections":[{"heading":"Co musisz zrozumieć","text":"Grubość mierzy się odpowiednim grubościomierzem w kilku punktach, unikając samej krawędzi. Dla pasa 25 mm szerokości i 3 mm grubości przekrój nominalny to 75 mm², ale dziurki i szwy go osłabiają."},{"heading":"Materiały i narzędzia w praktyce","text":"Zanim rozpoczniesz etap „Pomiar grubości, szerokości i tolerancji”, zapisz parametry próbki, warunki użytkowania, narzędzia i ograniczenia. Grubość mierzy się odpowiednim grubościomierzem w kilku punktach, unikając samej krawędzi. Dla pasa 25 mm szerokości i 3 mm grubości przekrój nominalny to 75 mm², ale dziurki i szwy go osłabiają."},{"heading":"Przykład i obliczenia","text":"Zmierz pięć punktów próbki, policz min/max i średnią; narysuj przekrój z otworem."},{"heading":"Błąd, który trzeba rozpoznać","text":"Pytanie kontrolne: Dlaczego 25×3=75 mm² nie jest dowodem nośności pasa? Pole nominalne nie uwzględnia jakości skóry, otworów, zmęczenia ani połączeń."},{"heading":"Ćwiczenie i weryfikacja","text":"Zmierz pięć punktów próbki, policz min/max i średnią; narysuj przekrój z otworem. Uzasadnij dobór i sprawdź wynik z prowadzącym; elementu demonstracyjnego nie używaj do pracy z żywym zwierzęciem ani pod obciążeniem."}],"references":[{"label":"Leather Working Group — leather manufacturing and responsible sourcing","url":"https://www.leatherworkinggroup.com/"},{"label":"The Leather Conservation Centre — care and conservation","url":"https://www.leatherconservation.org/"},{"label":"British Horse Society — horse welfare and tack","url":"https://www.bhs.org.uk/"}],"learning":{"intro":"Grubość mierzy się odpowiednim grubościomierzem w kilku punktach, unikając samej krawędzi. Dla pasa 25 mm szerokości i 3 mm grubości przekrój nominalny to 75 mm², ale dziurki i szwy go osłabiają.","situation":"Dlaczego 25×3=75 mm² nie jest dowodem nośności pasa?","task":"Zmierz pięć punktów próbki, policz min/max i średnią; narysuj przekrój z otworem.","question":"Dlaczego 25×3=75 mm² nie jest dowodem nośności pasa?","options":["Bo przekrój nie uwzględnia wad i koncentracji naprężeń.","Bo mnożenie milimetrów jest niedozwolone.","Bo grubość zawsze jest identyczna.","Bo metalowa sprzączka eliminuje ryzyko."],"correct":0,"explanation":"Pole nominalne nie uwzględnia jakości skóry, otworów, zmęczenia ani połączeń.","feedback":["Poprawnie. Pole nominalne nie uwzględnia jakości skóry, otworów, zmęczenia ani połączeń.","Nie. Pole nominalne nie uwzględnia jakości skóry, otworów, zmęczenia ani połączeń.","Nie. Pole nominalne nie uwzględnia jakości skóry, otworów, zmęczenia ani połączeń.","Nie. Pole nominalne nie uwzględnia jakości skóry, otworów, zmęczenia ani połączeń."]}}'::jsonb),
('rymarz',4,'5. Szablon i rozkrój pasa','{"curriculum_revision":11,"editorial_status":"review_needed","lesson_kind":"technical_curriculum","module":2,"illustration":"craft-rymarz","sections":[{"heading":"Co musisz zrozumieć","text":"Przed cięciem ustal długość użytkową, zapas na zawinięcie, liczbę otworów, szerokość i promienie końców. Nóż do skóry wymaga maty, stabilnego prowadzenia i ochrony dłoni; ćwicz najpierw na kartonie."},{"heading":"Materiały i narzędzia w praktyce","text":"Zanim rozpoczniesz etap „Szablon i rozkrój pasa”, zapisz parametry próbki, warunki użytkowania, narzędzia i ograniczenia. Przed cięciem ustal długość użytkową, zapas na zawinięcie, liczbę otworów, szerokość i promienie końców. Nóż do skóry wymaga maty, stabilnego prowadzenia i ochrony dłoni; ćwicz najpierw na kartonie."},{"heading":"Przykład i obliczenia","text":"Dla paska o długości użytkowej 110 cm i zawinięciu 8 cm oblicz minimum 118 cm plus ustalone wykończenie końca."},{"heading":"Błąd, który trzeba rozpoznać","text":"Pytanie kontrolne: Jaki błąd powstaje, gdy długość cięcia jest równa długości użytkowej bez zapasu na mocowanie? Brakuje materiału na zawinięcie i zakotwienie sprzączki."},{"heading":"Ćwiczenie i weryfikacja","text":"Dla paska o długości użytkowej 110 cm i zawinięciu 8 cm oblicz minimum 118 cm plus ustalone wykończenie końca. Uzasadnij dobór i sprawdź wynik z prowadzącym; elementu demonstracyjnego nie używaj do pracy z żywym zwierzęciem ani pod obciążeniem."}],"references":[{"label":"Leather Working Group — leather manufacturing and responsible sourcing","url":"https://www.leatherworkinggroup.com/"},{"label":"The Leather Conservation Centre — care and conservation","url":"https://www.leatherconservation.org/"},{"label":"British Horse Society — horse welfare and tack","url":"https://www.bhs.org.uk/"}],"learning":{"intro":"Przed cięciem ustal długość użytkową, zapas na zawinięcie, liczbę otworów, szerokość i promienie końców. Nóż do skóry wymaga maty, stabilnego prowadzenia i ochrony dłoni; ćwicz najpierw na kartonie.","situation":"Jaki błąd powstaje, gdy długość cięcia jest równa długości użytkowej bez zapasu na mocowanie?","task":"Dla paska o długości użytkowej 110 cm i zawinięciu 8 cm oblicz minimum 118 cm plus ustalone wykończenie końca.","question":"Jaki błąd powstaje, gdy długość cięcia jest równa długości użytkowej bez zapasu na mocowanie?","options":["Pas będzie zawsze zbyt szeroki.","Otrzymamy dwa pasy.","Zabraknie materiału na połączenie przy sprzączce.","Dziurki staną się automatycznie mocniejsze."],"correct":2,"explanation":"Brakuje materiału na zawinięcie i zakotwienie sprzączki.","feedback":["Nie. Brakuje materiału na zawinięcie i zakotwienie sprzączki.","Nie. Brakuje materiału na zawinięcie i zakotwienie sprzączki.","Poprawnie. Brakuje materiału na zawinięcie i zakotwienie sprzączki.","Nie. Brakuje materiału na zawinięcie i zakotwienie sprzączki."]}}'::jsonb),
('rymarz',5,'6. Narzędzia: szydło, wybijak, rowkownik i krawędziarka','{"curriculum_revision":11,"editorial_status":"review_needed","lesson_kind":"technical_curriculum","module":2,"illustration":"craft-rymarz","sections":[{"heading":"Co musisz zrozumieć","text":"Szydło otwiera otwór pod nić, wybijak tworzy otwór o określonej średnicy, rowkownik prowadzi linię szycia, a krawędziarka zaokrągla ostre krawędzie. Nie zastępuj precyzyjnego narzędzia przypadkowym gwoździem."},{"heading":"Materiały i narzędzia w praktyce","text":"Zanim rozpoczniesz etap „Narzędzia: szydło, wybijak, rowkownik i krawędziarka”, zapisz parametry próbki, warunki użytkowania, narzędzia i ograniczenia. Szydło otwiera otwór pod nić, wybijak tworzy otwór o określonej średnicy, rowkownik prowadzi linię szycia, a krawędziarka zaokrągla ostre krawędzie. Nie zastępuj precyzyjnego narzędzia przypadkowym gwoździem."},{"heading":"Przykład i obliczenia","text":"Na odpadzie zaznacz linię 4 mm od brzegu i wykonaj kartonową symulację odstępu ściegów 5 mm."},{"heading":"Błąd, który trzeba rozpoznać","text":"Pytanie kontrolne: Jak zmniejszyć ryzyko pęknięcia skóry przy serii otworów blisko krawędzi? Zachowaj odpowiedni margines, rozstaw i geometrię otworów według projektu."},{"heading":"Ćwiczenie i weryfikacja","text":"Na odpadzie zaznacz linię 4 mm od brzegu i wykonaj kartonową symulację odstępu ściegów 5 mm. Uzasadnij dobór i sprawdź wynik z prowadzącym; elementu demonstracyjnego nie używaj do pracy z żywym zwierzęciem ani pod obciążeniem."}],"references":[{"label":"Leather Working Group — leather manufacturing and responsible sourcing","url":"https://www.leatherworkinggroup.com/"},{"label":"The Leather Conservation Centre — care and conservation","url":"https://www.leatherconservation.org/"},{"label":"British Horse Society — horse welfare and tack","url":"https://www.bhs.org.uk/"}],"learning":{"intro":"Szydło otwiera otwór pod nić, wybijak tworzy otwór o określonej średnicy, rowkownik prowadzi linię szycia, a krawędziarka zaokrągla ostre krawędzie. Nie zastępuj precyzyjnego narzędzia przypadkowym gwoździem.","situation":"Jak zmniejszyć ryzyko pęknięcia skóry przy serii otworów blisko krawędzi?","task":"Na odpadzie zaznacz linię 4 mm od brzegu i wykonaj kartonową symulację odstępu ściegów 5 mm.","question":"Jak zmniejszyć ryzyko pęknięcia skóry przy serii otworów blisko krawędzi?","options":["Zwiększ otwory bez zmiany odstępu.","Dobierz margines i rozstaw do konstrukcji.","Wykonuj otwory jak najbliżej brzegu.","Zastąp szew przypadkowymi nacięciami."],"correct":1,"explanation":"Zachowaj odpowiedni margines, rozstaw i geometrię otworów według projektu.","feedback":["Nie. Zachowaj odpowiedni margines, rozstaw i geometrię otworów według projektu.","Poprawnie. Zachowaj odpowiedni margines, rozstaw i geometrię otworów według projektu.","Nie. Zachowaj odpowiedni margines, rozstaw i geometrię otworów według projektu.","Nie. Zachowaj odpowiedni margines, rozstaw i geometrię otworów według projektu."]}}'::jsonb),
('rymarz',6,'7. Ścieg siodlarski i kontrola naprężenia','{"curriculum_revision":11,"editorial_status":"review_needed","lesson_kind":"technical_curriculum","module":3,"illustration":"craft-rymarz","sections":[{"heading":"Co musisz zrozumieć","text":"Ścieg siodlarski wykonuje się dwiema igłami na jednej nici, przeprowadzając je przez te same otwory z przeciwnych stron. Regularność otworów i równy naciąg są istotniejsze od dekoracyjnego wyglądu."},{"heading":"Materiały i narzędzia w praktyce","text":"Zanim rozpoczniesz etap „Ścieg siodlarski i kontrola naprężenia”, zapisz parametry próbki, warunki użytkowania, narzędzia i ograniczenia. Ścieg siodlarski wykonuje się dwiema igłami na jednej nici, przeprowadzając je przez te same otwory z przeciwnych stron. Regularność otworów i równy naciąg są istotniejsze od dekoracyjnego wyglądu."},{"heading":"Przykład i obliczenia","text":"Narysuj przekrój czterech otworów i trasę dwóch końców nici; porównaj z luźnym szwem na próbce."},{"heading":"Błąd, który trzeba rozpoznać","text":"Pytanie kontrolne: Co może się stać, jeśli każdą kolejną pętlę zaciska się z inną siłą? Nierówne napięcie powoduje falowanie szwu i miejscowe przeciążenia."},{"heading":"Ćwiczenie i weryfikacja","text":"Narysuj przekrój czterech otworów i trasę dwóch końców nici; porównaj z luźnym szwem na próbce. Uzasadnij dobór i sprawdź wynik z prowadzącym; elementu demonstracyjnego nie używaj do pracy z żywym zwierzęciem ani pod obciążeniem."}],"references":[{"label":"Leather Working Group — leather manufacturing and responsible sourcing","url":"https://www.leatherworkinggroup.com/"},{"label":"The Leather Conservation Centre — care and conservation","url":"https://www.leatherconservation.org/"},{"label":"British Horse Society — horse welfare and tack","url":"https://www.bhs.org.uk/"}],"learning":{"intro":"Ścieg siodlarski wykonuje się dwiema igłami na jednej nici, przeprowadzając je przez te same otwory z przeciwnych stron. Regularność otworów i równy naciąg są istotniejsze od dekoracyjnego wyglądu.","situation":"Co może się stać, jeśli każdą kolejną pętlę zaciska się z inną siłą?","task":"Narysuj przekrój czterech otworów i trasę dwóch końców nici; porównaj z luźnym szwem na próbce.","question":"Co może się stać, jeśli każdą kolejną pętlę zaciska się z inną siłą?","options":["Nierówne naprężenie i deformacja szwu.","Automatycznie rośnie odporność na rozdarcie.","Nić nie styka się ze skórą.","Długość pasa przestaje mieć znaczenie."],"correct":0,"explanation":"Nierówne napięcie powoduje falowanie szwu i miejscowe przeciążenia.","feedback":["Poprawnie. Nierówne napięcie powoduje falowanie szwu i miejscowe przeciążenia.","Nie. Nierówne napięcie powoduje falowanie szwu i miejscowe przeciążenia.","Nie. Nierówne napięcie powoduje falowanie szwu i miejscowe przeciążenia.","Nie. Nierówne napięcie powoduje falowanie szwu i miejscowe przeciążenia."]}}'::jsonb),
('rymarz',7,'8. Sprzączki, nity i mocowania','{"curriculum_revision":11,"editorial_status":"review_needed","lesson_kind":"technical_curriculum","module":3,"illustration":"craft-rymarz","sections":[{"heading":"Co musisz zrozumieć","text":"Dobór sprzączki obejmuje szerokość wewnętrzną, materiał, krawędzie, korozję i sposób połączenia. Nity nie są zamiennikiem każdego szwu; w konstrukcjach obciążanych liczą się obciążenia, jakość montażu i dokumentacja."},{"heading":"Materiały i narzędzia w praktyce","text":"Zanim rozpoczniesz etap „Sprzączki, nity i mocowania”, zapisz parametry próbki, warunki użytkowania, narzędzia i ograniczenia. Dobór sprzączki obejmuje szerokość wewnętrzną, materiał, krawędzie, korozję i sposób połączenia. Nity nie są zamiennikiem każdego szwu; w konstrukcjach obciążanych liczą się obciążenia, jakość montażu i dokumentacja."},{"heading":"Przykład i obliczenia","text":"Zaprojektuj nieobciążaną atrapę paska z wymiarami sprzączki 25 mm i pasem o nominalnej szerokości 25 mm."},{"heading":"Błąd, który trzeba rozpoznać","text":"Pytanie kontrolne: Dlaczego dwie sprzączki opisane jako 25 mm nie muszą być równoważne? Różnią się geometrią, materiałem, wykończeniem i deklarowanymi parametrami."},{"heading":"Ćwiczenie i weryfikacja","text":"Zaprojektuj nieobciążaną atrapę paska z wymiarami sprzączki 25 mm i pasem o nominalnej szerokości 25 mm. Uzasadnij dobór i sprawdź wynik z prowadzącym; elementu demonstracyjnego nie używaj do pracy z żywym zwierzęciem ani pod obciążeniem."}],"references":[{"label":"Leather Working Group — leather manufacturing and responsible sourcing","url":"https://www.leatherworkinggroup.com/"},{"label":"The Leather Conservation Centre — care and conservation","url":"https://www.leatherconservation.org/"},{"label":"British Horse Society — horse welfare and tack","url":"https://www.bhs.org.uk/"}],"learning":{"intro":"Dobór sprzączki obejmuje szerokość wewnętrzną, materiał, krawędzie, korozję i sposób połączenia. Nity nie są zamiennikiem każdego szwu; w konstrukcjach obciążanych liczą się obciążenia, jakość montażu i dokumentacja.","situation":"Dlaczego dwie sprzączki opisane jako 25 mm nie muszą być równoważne?","task":"Zaprojektuj nieobciążaną atrapę paska z wymiarami sprzączki 25 mm i pasem o nominalnej szerokości 25 mm.","question":"Dlaczego dwie sprzączki opisane jako 25 mm nie muszą być równoważne?","options":["Bo rozmiar określa wyłącznie kolor.","Bo metal nie koroduje.","Bo każda ma certyfikat do pracy z końmi.","Bo poza szerokością liczy się konstrukcja i parametry."],"correct":3,"explanation":"Różnią się geometrią, materiałem, wykończeniem i deklarowanymi parametrami.","feedback":["Nie. Różnią się geometrią, materiałem, wykończeniem i deklarowanymi parametrami.","Nie. Różnią się geometrią, materiałem, wykończeniem i deklarowanymi parametrami.","Nie. Różnią się geometrią, materiałem, wykończeniem i deklarowanymi parametrami.","Poprawnie. Różnią się geometrią, materiałem, wykończeniem i deklarowanymi parametrami."]}}'::jsonb),
('rymarz',8,'9. Dopasowanie uprzęży i dobrostan zwierzęcia','{"curriculum_revision":11,"editorial_status":"review_needed","lesson_kind":"technical_curriculum","module":3,"illustration":"craft-rymarz","sections":[{"heading":"Co musisz zrozumieć","text":"Punkty nacisku, tarcie, zakres ruchu i rozkład siły wpływają na komfort zwierzęcia. Uczeń nie powinien samodzielnie dopasowywać obciążonej uprzęży ani oceniać jej bezpieczeństwa bez doświadczonego rymarza i specjalisty od pracy z końmi."},{"heading":"Materiały i narzędzia w praktyce","text":"Zanim rozpoczniesz etap „Dopasowanie uprzęży i dobrostan zwierzęcia”, zapisz parametry próbki, warunki użytkowania, narzędzia i ograniczenia. Punkty nacisku, tarcie, zakres ruchu i rozkład siły wpływają na komfort zwierzęcia. Uczeń nie powinien samodzielnie dopasowywać obciążonej uprzęży ani oceniać jej bezpieczeństwa bez doświadczonego rymarza i specjalisty od pracy z końmi."},{"heading":"Przykład i obliczenia","text":"Na sylwetce konia zaznacz miejsca możliwego ucisku i ruchu pasków; opisz, co wymaga oceny na żywym zwierzęciu."},{"heading":"Błąd, który trzeba rozpoznać","text":"Pytanie kontrolne: Koń ma otarcie pod pasem, mimo że klamra nie jest uszkodzona. Co sprawdzić? Dopasowanie, tarcie, stan materiału i nacisk, a nie tylko metalowe elementy."},{"heading":"Ćwiczenie i weryfikacja","text":"Na sylwetce konia zaznacz miejsca możliwego ucisku i ruchu pasków; opisz, co wymaga oceny na żywym zwierzęciu. Uzasadnij dobór i sprawdź wynik z prowadzącym; elementu demonstracyjnego nie używaj do pracy z żywym zwierzęciem ani pod obciążeniem."}],"references":[{"label":"Leather Working Group — leather manufacturing and responsible sourcing","url":"https://www.leatherworkinggroup.com/"},{"label":"The Leather Conservation Centre — care and conservation","url":"https://www.leatherconservation.org/"},{"label":"British Horse Society — horse welfare and tack","url":"https://www.bhs.org.uk/"}],"learning":{"intro":"Punkty nacisku, tarcie, zakres ruchu i rozkład siły wpływają na komfort zwierzęcia. Uczeń nie powinien samodzielnie dopasowywać obciążonej uprzęży ani oceniać jej bezpieczeństwa bez doświadczonego rymarza i specjalisty od pracy z końmi.","situation":"Koń ma otarcie pod pasem, mimo że klamra nie jest uszkodzona. Co sprawdzić?","task":"Na sylwetce konia zaznacz miejsca możliwego ucisku i ruchu pasków; opisz, co wymaga oceny na żywym zwierzęciu.","question":"Koń ma otarcie pod pasem, mimo że klamra nie jest uszkodzona. Co sprawdzić?","options":["Wyłącznie kolor skóry.","Wyłącznie połysk klamry.","Nacisk, tarcie i dopasowanie całej uprzęży.","Tylko datę zakupu."],"correct":2,"explanation":"Dopasowanie, tarcie, stan materiału i nacisk, a nie tylko metalowe elementy.","feedback":["Nie. Dopasowanie, tarcie, stan materiału i nacisk, a nie tylko metalowe elementy.","Nie. Dopasowanie, tarcie, stan materiału i nacisk, a nie tylko metalowe elementy.","Poprawnie. Dopasowanie, tarcie, stan materiału i nacisk, a nie tylko metalowe elementy.","Nie. Dopasowanie, tarcie, stan materiału i nacisk, a nie tylko metalowe elementy."]}}'::jsonb),
('rymarz',9,'10. Konserwacja, wilgoć i korozja','{"curriculum_revision":11,"editorial_status":"review_needed","lesson_kind":"technical_curriculum","module":4,"illustration":"craft-rymarz","sections":[{"heading":"Co musisz zrozumieć","text":"Nadmierne wysuszenie może powodować sztywność i pękanie, a zawilgocenie i niewłaściwe przechowywanie sprzyjają degradacji i pleśni. Preparat konserwujący dobiera się do konkretnego wykończenia skóry; nie ukrywaj wad smarem."},{"heading":"Materiały i narzędzia w praktyce","text":"Zanim rozpoczniesz etap „Konserwacja, wilgoć i korozja”, zapisz parametry próbki, warunki użytkowania, narzędzia i ograniczenia. Nadmierne wysuszenie może powodować sztywność i pękanie, a zawilgocenie i niewłaściwe przechowywanie sprzyjają degradacji i pleśni. Preparat konserwujący dobiera się do konkretnego wykończenia skóry; nie ukrywaj wad smarem."},{"heading":"Przykład i obliczenia","text":"Przygotuj kartę kontroli: powierzchnia, szwy, otwory, sprzączki, korozja, zapach, odkształcenia."},{"heading":"Błąd, który trzeba rozpoznać","text":"Pytanie kontrolne: Dlaczego mocne natłuszczenie nie naprawi pęknięcia przy otworze? Pęknięcie to uszkodzenie struktury, nie tylko utrata połysku."},{"heading":"Ćwiczenie i weryfikacja","text":"Przygotuj kartę kontroli: powierzchnia, szwy, otwory, sprzączki, korozja, zapach, odkształcenia. Uzasadnij dobór i sprawdź wynik z prowadzącym; elementu demonstracyjnego nie używaj do pracy z żywym zwierzęciem ani pod obciążeniem."}],"references":[{"label":"Leather Working Group — leather manufacturing and responsible sourcing","url":"https://www.leatherworkinggroup.com/"},{"label":"The Leather Conservation Centre — care and conservation","url":"https://www.leatherconservation.org/"},{"label":"British Horse Society — horse welfare and tack","url":"https://www.bhs.org.uk/"}],"learning":{"intro":"Nadmierne wysuszenie może powodować sztywność i pękanie, a zawilgocenie i niewłaściwe przechowywanie sprzyjają degradacji i pleśni. Preparat konserwujący dobiera się do konkretnego wykończenia skóry; nie ukrywaj wad smarem.","situation":"Dlaczego mocne natłuszczenie nie naprawi pęknięcia przy otworze?","task":"Przygotuj kartę kontroli: powierzchnia, szwy, otwory, sprzączki, korozja, zapach, odkształcenia.","question":"Dlaczego mocne natłuszczenie nie naprawi pęknięcia przy otworze?","options":["Bo uszkodzenie strukturalne wymaga oceny lub wymiany.","Bo tłuszcz zwiększa średnicę sprzączki.","Bo skóra nie wchłania żadnych substancji.","Bo każdy pas jest odporny na pękanie."],"correct":0,"explanation":"Pęknięcie to uszkodzenie struktury, nie tylko utrata połysku.","feedback":["Poprawnie. Pęknięcie to uszkodzenie struktury, nie tylko utrata połysku.","Nie. Pęknięcie to uszkodzenie struktury, nie tylko utrata połysku.","Nie. Pęknięcie to uszkodzenie struktury, nie tylko utrata połysku.","Nie. Pęknięcie to uszkodzenie struktury, nie tylko utrata połysku."]}}'::jsonb),
('rymarz',10,'11. Diagnostyka i decyzja: naprawa czy wycofanie','{"curriculum_revision":11,"editorial_status":"review_needed","lesson_kind":"technical_curriculum","module":4,"illustration":"craft-rymarz","sections":[{"heading":"Co musisz zrozumieć","text":"Ocena obejmuje nacięcia, rozwarstwienia, przetarcia, wyciągnięte otwory, pęknięte szwy i korozję okuć. Elementy krytyczne dla bezpieczeństwa zwierzęcia i człowieka należy wycofać z użycia do czasu profesjonalnej oceny."},{"heading":"Materiały i narzędzia w praktyce","text":"Zanim rozpoczniesz etap „Diagnostyka i decyzja: naprawa czy wycofanie”, zapisz parametry próbki, warunki użytkowania, narzędzia i ograniczenia. Ocena obejmuje nacięcia, rozwarstwienia, przetarcia, wyciągnięte otwory, pęknięte szwy i korozję okuć. Elementy krytyczne dla bezpieczeństwa zwierzęcia i człowieka należy wycofać z użycia do czasu profesjonalnej oceny."},{"heading":"Przykład i obliczenia","text":"Dla trzech opisanych przypadków napisz decyzję: kosmetyka, naprawa pod nadzorem lub wycofanie."},{"heading":"Błąd, który trzeba rozpoznać","text":"Pytanie kontrolne: Pas nośny ma pęknięcie 6 mm od otworu klamry. Co zrobić przed kolejnym użyciem? Wycofać z użycia i przekazać do oceny, zamiast maskować uszkodzenie."},{"heading":"Ćwiczenie i weryfikacja","text":"Dla trzech opisanych przypadków napisz decyzję: kosmetyka, naprawa pod nadzorem lub wycofanie. Uzasadnij dobór i sprawdź wynik z prowadzącym; elementu demonstracyjnego nie używaj do pracy z żywym zwierzęciem ani pod obciążeniem."}],"references":[{"label":"Leather Working Group — leather manufacturing and responsible sourcing","url":"https://www.leatherworkinggroup.com/"},{"label":"The Leather Conservation Centre — care and conservation","url":"https://www.leatherconservation.org/"},{"label":"British Horse Society — horse welfare and tack","url":"https://www.bhs.org.uk/"}],"learning":{"intro":"Ocena obejmuje nacięcia, rozwarstwienia, przetarcia, wyciągnięte otwory, pęknięte szwy i korozję okuć. Elementy krytyczne dla bezpieczeństwa zwierzęcia i człowieka należy wycofać z użycia do czasu profesjonalnej oceny.","situation":"Pas nośny ma pęknięcie 6 mm od otworu klamry. Co zrobić przed kolejnym użyciem?","task":"Dla trzech opisanych przypadków napisz decyzję: kosmetyka, naprawa pod nadzorem lub wycofanie.","question":"Pas nośny ma pęknięcie 6 mm od otworu klamry. Co zrobić przed kolejnym użyciem?","options":["Wypolerować i używać dalej.","Dodać farbę i mocniej zapiąć.","Wyciąć kolejną dziurkę tuż obok.","Wycofać i poddać fachowej ocenie."],"correct":3,"explanation":"Wycofać z użycia i przekazać do oceny, zamiast maskować uszkodzenie.","feedback":["Nie. Wycofać z użycia i przekazać do oceny, zamiast maskować uszkodzenie.","Nie. Wycofać z użycia i przekazać do oceny, zamiast maskować uszkodzenie.","Nie. Wycofać z użycia i przekazać do oceny, zamiast maskować uszkodzenie.","Poprawnie. Wycofać z użycia i przekazać do oceny, zamiast maskować uszkodzenie."]}}'::jsonb),
('rymarz',11,'12. Projekt końcowy: pasek demonstracyjny i kosztorys','{"curriculum_revision":11,"editorial_status":"review_needed","lesson_kind":"technical_curriculum","module":4,"illustration":"craft-rymarz","sections":[{"heading":"Co musisz zrozumieć","text":"Zaprojektuj nieobciążany model paska 25 mm × 118 cm, z rozstawem otworów, zawinięciem i oznaczeniem kierunku włókien. Koszt obejmuje skórę, okucia, nić, odpady, robociznę i kontrolę. Nie deklaruj dopuszczenia do użycia jeździeckiego."},{"heading":"Materiały i narzędzia w praktyce","text":"Zanim rozpoczniesz etap „Projekt końcowy: pasek demonstracyjny i kosztorys”, zapisz parametry próbki, warunki użytkowania, narzędzia i ograniczenia. Zaprojektuj nieobciążany model paska 25 mm × 118 cm, z rozstawem otworów, zawinięciem i oznaczeniem kierunku włókien. Koszt obejmuje skórę, okucia, nić, odpady, robociznę i kontrolę. Nie deklaruj dopuszczenia do użycia jeździeckiego."},{"heading":"Przykład i obliczenia","text":"Jeśli materiał kosztuje 70 zł, okucia 18 zł, nić 4 zł, robocizna 90 zł, odpady 8 zł, policz koszt 190 zł przed marżą."},{"heading":"Błąd, który trzeba rozpoznać","text":"Pytanie kontrolne: Koszt 190 zł, a cena 240 zł. Ile wynosi marża brutto w zł i procent ceny? 50 zł i około 20,8% ceny sprzedaży."},{"heading":"Ćwiczenie i weryfikacja","text":"Jeśli materiał kosztuje 70 zł, okucia 18 zł, nić 4 zł, robocizna 90 zł, odpady 8 zł, policz koszt 190 zł przed marżą. Uzasadnij dobór i sprawdź wynik z prowadzącym; elementu demonstracyjnego nie używaj do pracy z żywym zwierzęciem ani pod obciążeniem."}],"references":[{"label":"Leather Working Group — leather manufacturing and responsible sourcing","url":"https://www.leatherworkinggroup.com/"},{"label":"The Leather Conservation Centre — care and conservation","url":"https://www.leatherconservation.org/"},{"label":"British Horse Society — horse welfare and tack","url":"https://www.bhs.org.uk/"}],"learning":{"intro":"Zaprojektuj nieobciążany model paska 25 mm × 118 cm, z rozstawem otworów, zawinięciem i oznaczeniem kierunku włókien. Koszt obejmuje skórę, okucia, nić, odpady, robociznę i kontrolę. Nie deklaruj dopuszczenia do użycia jeździeckiego.","situation":"Koszt 190 zł, a cena 240 zł. Ile wynosi marża brutto w zł i procent ceny?","task":"Jeśli materiał kosztuje 70 zł, okucia 18 zł, nić 4 zł, robocizna 90 zł, odpady 8 zł, policz koszt 190 zł przed marżą.","question":"Koszt 190 zł, a cena 240 zł. Ile wynosi marża brutto w zł i procent ceny?","options":["50 zł i 50%.","50 zł i 20,8%.","240 zł i 20,8%.","190 zł i 50%."],"correct":1,"explanation":"50 zł i około 20,8% ceny sprzedaży.","feedback":["Nie. 50 zł i około 20,8% ceny sprzedaży.","Poprawnie. 50 zł i około 20,8% ceny sprzedaży.","Nie. 50 zł i około 20,8% ceny sprzedaży.","Nie. 50 zł i około 20,8% ceny sprzedaży."]}}'::jsonb)
